import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-128: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short128', durationInSeconds: 36.9, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short128: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(32.8);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{text: "US-ONLY AI"}, {text: "COSTS 10% MORE", accent: true}];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.0)}>
        <CoverImage src="projects/short-128/cover.png" out={secToFrame(3.0) - 10} />
        <HookTitle hold onDark kicker="AI API PRICING" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(4.9)}>
        <ToolCard name="US-only inference" tagline="It costs extra." chip="+10%" at={secToFrame(3.0) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="keep data in" v="the US" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(10.3)}>
        <ToolCard name="Claude" tagline="inference_geo: us" chip="1.1x" at={secToFrame(4.9) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="multiplier" v="1.1x" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(13.4)}>
        <ToolCard name="What it covers" tagline="Every price." chip="ALL" at={secToFrame(10.3) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input" v="1.1x" />
            <Line k="output" v="1.1x" />
            <Line k="cache" v="1.1x" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(17.8)}>
        <ToolCard name="OpenAI" tagline="Regional processing." chip="+10%" at={secToFrame(13.4) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="uplift" v="10%" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(19.5)}>
        <ToolCard name="The same tax" tagline="Both vendors." chip="10%" at={secToFrame(17.8) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Claude" v="+10%" bad />
            <Line k="OpenAI" v="+10%" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(22.7)}>
        <ToolCard name="Claude" tagline="Version 4.6 and later." chip="4.6+" at={secToFrame(19.5) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="applies from" v="4.6 on" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(27.1)}>
        <ToolCard name="OpenAI" tagline="Models after Mar 5, 2026." chip="2026" at={secToFrame(22.7) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="released after" v="Mar 5, 2026" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(30.7)}>
        <ToolCard name="A $2.00 model" tagline="With US-only." chip="$2.20" at={secToFrame(27.1) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="$2.00 x 1.1" v="$2.20" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(32.8)}>
        <ToolCard name="Same price tag" tagline="At both." chip="=" at={secToFrame(30.7) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Claude" v="+10%" />
            <Line k="OpenAI" v="+10%" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-128/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI API PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          US-only AI costs 10% more.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short128;
